
-- Course 3: تكوين سياسات SLA (4 lessons)
INSERT INTO training_lessons (course_id, title, content, sort_order, duration_minutes) VALUES
('11111111-1111-1111-1111-111111111103', 'مفهوم اتفاقية مستوى الخدمة SLA', E'# مفهوم اتفاقية مستوى الخدمة (SLA)\n\nاتفاقية مستوى الخدمة هي عقد بين مقدم الخدمة والمستفيد يحدد:\n\n## المكونات الأساسية\n- **زمن الاستجابة الأولى**: المدة المسموحة للرد الأولي\n- **زمن الحل**: المدة القصوى لحل التذكرة\n- **مستويات الأولوية**: تحديد الأولويات وتأثيرها على الأوقات\n\n## أهمية SLA\n1. ضمان جودة الخدمة المقدمة\n2. قياس الأداء بموضوعية\n3. تحسين رضا المستفيدين\n4. توفير إطار واضح للتوقعات', 1, 8),
('11111111-1111-1111-1111-111111111103', 'إنشاء سياسة SLA جديدة', E'# إنشاء سياسة SLA جديدة\n\n## خطوات الإنشاء\n1. انتقل إلى **الإعدادات** > **سياسات SLA**\n2. اضغط على **إضافة سياسة جديدة**\n3. حدد مستوى الأولوية\n4. أدخل أوقات الاستجابة والحل\n\n## إعدادات الأولوية\n| الأولوية | استجابة أولى | وقت الحل |\n|----------|-------------|----------|\n| حرجة | 15 دقيقة | ساعتان |\n| عالية | 30 دقيقة | 4 ساعات |\n| متوسطة | ساعة | 8 ساعات |\n| منخفضة | 4 ساعات | 24 ساعة |', 2, 10),
('11111111-1111-1111-1111-111111111103', 'التنبيهات والتصعيد التلقائي', E'# التنبيهات والتصعيد التلقائي\n\n## أنواع التنبيهات\n- **تنبيه اقتراب الموعد**: قبل انتهاء المهلة بـ 25%\n- **تنبيه تجاوز SLA**: عند تجاوز المهلة المحددة\n- **تنبيه التصعيد**: عند تفعيل التصعيد التلقائي\n\n## مستويات التصعيد\n1. **المستوى الأول**: إشعار الوكيل المسؤول\n2. **المستوى الثاني**: إشعار مدير القسم\n3. **المستوى الثالث**: إشعار المدير التنفيذي\n\n## إعداد التصعيد\nيمكن تخصيص قواعد التصعيد من صفحة إعدادات SLA', 3, 8),
('11111111-1111-1111-1111-111111111103', 'تقارير الالتزام بـ SLA', E'# تقارير الالتزام بـ SLA\n\n## مؤشرات الأداء الرئيسية\n- **نسبة الالتزام**: النسبة المئوية للتذاكر المحلولة ضمن SLA\n- **متوسط وقت الاستجابة**: المتوسط الفعلي للاستجابة الأولى\n- **متوسط وقت الحل**: المتوسط الفعلي لحل التذاكر\n\n## قراءة التقارير\n1. افتح **التقارير** > **التزام SLA**\n2. اختر الفترة الزمنية\n3. فلتر حسب القسم أو الأولوية\n4. صدّر التقرير بصيغة PDF', 4, 7),

-- Course 4: تكامل كلاسيرا المتقدم (4 lessons)
('11111111-1111-1111-1111-111111111104', 'نظرة عامة على تكامل كلاسيرا', E'# نظرة عامة على تكامل كلاسيرا\n\n## ما هو التكامل؟\nيتيح ربط نظام التذاكر بمنصة كلاسيرا التعليمية لـ:\n- استقبال طلبات الدعم من كلاسيرا تلقائياً\n- مزامنة حالة التذاكر مع المنصة\n- إرسال التحديثات للمستفيدين عبر كلاسيرا\n\n## المتطلبات\n1. حساب مدير على كلاسيرا\n2. مفتاح API صالح\n3. تفعيل وحدة التكامل', 1, 8),
('11111111-1111-1111-1111-111111111104', 'إعداد الاتصال والمزامنة', E'# إعداد الاتصال والمزامنة\n\n## خطوات التهيئة\n1. افتح **الإعدادات** > **تكاملات كلاسيرا**\n2. أدخل عنوان API ومفتاح الوصول\n3. اختبر الاتصال\n4. فعّل المزامنة التلقائية\n\n## خيارات المزامنة\n- **أحادي الاتجاه**: من كلاسيرا للنظام فقط\n- **ثنائي الاتجاه**: مزامنة كاملة بين النظامين\n\n## جدولة المزامنة\nيمكن ضبط فترات المزامنة: كل 5 أو 15 أو 30 دقيقة', 2, 10),
('11111111-1111-1111-1111-111111111104', 'ربط الوحدات والخدمات', E'# ربط الوحدات والخدمات\n\n## خريطة الربط\nكل وحدة في كلاسيرا يمكن ربطها بخدمة في النظام:\n\n| وحدة كلاسيرا | الخدمة المقابلة |\n|-------------|----------------|\n| إدارة الطلاب | دعم الطلاب |\n| الشؤون المالية | الدعم المالي |\n| التسجيل | خدمات القبول |\n\n## إعداد الربط\n1. افتح صفحة **تكاملات كلاسيرا**\n2. اختر الوحدة من القائمة\n3. حدد الخدمة المقابلة\n4. احفظ الإعدادات', 3, 8),
('11111111-1111-1111-1111-111111111104', 'استكشاف الأخطاء ومراقبة السجلات', E'# استكشاف الأخطاء ومراقبة السجلات\n\n## الأخطاء الشائعة\n- **خطأ اتصال**: تحقق من عنوان API والمفتاح\n- **فشل المزامنة**: تأكد من صلاحيات الحساب\n- **بيانات مفقودة**: راجع خريطة الربط\n\n## سجل المزامنة\nيعرض جميع عمليات المزامنة مع:\n- التاريخ والوقت\n- الحالة (نجاح/فشل)\n- عدد السجلات المُعالجة\n- رسائل الخطأ إن وجدت', 4, 7),

-- Course 5: سير العمل والأتمتة (4 lessons)
('11111111-1111-1111-1111-111111111105', 'مقدمة في الأتمتة', E'# مقدمة في الأتمتة\n\n## لماذا الأتمتة؟\n- تقليل المهام اليدوية المتكررة\n- تسريع معالجة التذاكر\n- ضمان تطبيق السياسات بشكل موحد\n\n## أنواع قواعد الأتمتة\n1. **عند الإنشاء**: تنفذ عند إنشاء تذكرة جديدة\n2. **عند التحديث**: تنفذ عند تغيير حالة أو بيانات التذكرة\n3. **مجدولة**: تنفذ دورياً حسب جدول زمني\n\n## أمثلة عملية\n- تعيين تذكرة تلقائياً حسب القسم\n- إرسال إشعار عند تغيير الأولوية\n- إغلاق التذاكر غير النشطة', 1, 9),
('11111111-1111-1111-1111-111111111105', 'إنشاء قواعد أتمتة', E'# إنشاء قواعد أتمتة\n\n## مكونات القاعدة\n- **المحفّز (Trigger)**: الحدث الذي يبدأ التنفيذ\n- **الشروط (Conditions)**: متى يتم التنفيذ\n- **الإجراءات (Actions)**: ما يتم تنفيذه\n\n## خطوات الإنشاء\n1. افتح **الإعدادات** > **الأتمتة**\n2. اضغط **إضافة قاعدة جديدة**\n3. اختر المحفز المناسب\n4. حدد الشروط\n5. أضف الإجراءات المطلوبة\n6. فعّل القاعدة\n\n## نصائح\n- ابدأ بقواعد بسيطة\n- اختبر القاعدة قبل التفعيل\n- راجع سجل التنفيذ دورياً', 2, 12),
('11111111-1111-1111-1111-111111111105', 'سير العمل ومراحل الموافقة', E'# سير العمل ومراحل الموافقة\n\n## تصميم سير العمل\nيتكون سير العمل من مراحل متتابعة:\n1. **تقديم الطلب**: المستفيد يرسل التذكرة\n2. **المراجعة الأولية**: فحص التذكرة\n3. **الموافقة**: اعتماد من المسؤول\n4. **التنفيذ**: حل المشكلة\n5. **الإغلاق**: تأكيد الحل\n\n## إعداد مراحل الموافقة\n- حدد المراحل المطلوبة لكل خدمة\n- عيّن المعتمدين لكل مرحلة\n- اضبط المهل الزمنية\n- فعّل التصعيد التلقائي', 3, 10),
('11111111-1111-1111-1111-111111111105', 'مراقبة وتحسين الأتمتة', E'# مراقبة وتحسين الأتمتة\n\n## لوحة مراقبة الأتمتة\n- عدد القواعد النشطة\n- عدد التنفيذات اليومية\n- نسبة النجاح\n- الأخطاء الأخيرة\n\n## تحليل الأداء\n1. راجع **سجل الأتمتة** أسبوعياً\n2. حدد القواعد الأكثر استخداماً\n3. أوقف القواعد غير الفعّالة\n4. حسّن الشروط بناءً على البيانات\n\n## أفضل الممارسات\n- وثّق كل قاعدة بوصف واضح\n- استخدم أسماء وصفية\n- راجع القواعد كل شهر', 4, 8),

-- Course 6: التقارير والتحليلات (4 lessons)
('11111111-1111-1111-1111-111111111106', 'لوحة المعلومات الرئيسية', E'# لوحة المعلومات الرئيسية\n\n## مؤشرات الأداء KPIs\n- **إجمالي التذاكر**: عدد التذاكر في الفترة المحددة\n- **معدل الحل**: نسبة التذاكر المحلولة\n- **متوسط وقت الحل**: المدة المتوسطة لحل التذاكر\n- **رضا المستفيدين**: تقييم CSAT الإجمالي\n\n## الرسوم البيانية\n1. توزيع التذاكر حسب الحالة\n2. اتجاه التذاكر الشهري\n3. أداء الوكلاء\n4. توزيع الأولويات\n\n## تخصيص اللوحة\nيمكن إضافة أو إزالة الأدوات حسب احتياجاتك', 1, 8),
('11111111-1111-1111-1111-111111111106', 'التقارير المتقدمة', E'# التقارير المتقدمة\n\n## أنواع التقارير\n- **تقرير الأداء**: أداء الوكلاء والأقسام\n- **تقرير SLA**: نسب الالتزام بالاتفاقيات\n- **تقرير الحجم**: حجم التذاكر وتوزيعها\n- **تقرير CSAT**: رضا المستفيدين\n\n## إنشاء تقرير مخصص\n1. افتح **التقارير** > **منشئ التقارير**\n2. اختر نوع التقرير\n3. حدد الفلاتر والأبعاد\n4. اختر طريقة العرض\n5. احفظ التقرير للاستخدام المتكرر', 2, 10),
('11111111-1111-1111-1111-111111111106', 'تحليل رضا المستفيدين CSAT', E'# تحليل رضا المستفيدين CSAT\n\n## جمع التقييمات\n- يتم إرسال استبيان تلقائي بعد إغلاق التذكرة\n- مقياس من 1 إلى 5 نجوم\n- تعليق نصي اختياري\n\n## تحليل النتائج\n- **CSAT Score**: النسبة المئوية للتقييمات الإيجابية (4-5)\n- **NPS Score**: صافي نقاط الترويج\n- **تحليل المشاعر**: تحليل التعليقات بالذكاء الاصطناعي\n\n## تحسين الرضا\n1. حدد أنماط الشكاوى المتكررة\n2. درّب الوكلاء على نقاط الضعف\n3. حسّن العمليات بناءً على التغذية الراجعة', 3, 9),
('11111111-1111-1111-1111-111111111106', 'تصدير ومشاركة التقارير', E'# تصدير ومشاركة التقارير\n\n## صيغ التصدير\n- **PDF**: للطباعة والأرشفة\n- **Excel**: للتحليل المتقدم\n- **CSV**: للتكامل مع أنظمة أخرى\n\n## جدولة التقارير\n1. افتح التقرير المطلوب\n2. اضغط **جدولة**\n3. حدد التكرار (يومي/أسبوعي/شهري)\n4. أدخل عناوين البريد الإلكتروني\n5. فعّل الجدولة\n\n## مشاركة اللوحات\n- أنشئ رابط مشاركة مباشر\n- حدد صلاحيات العرض\n- تتبع من يطلع على التقرير', 4, 7),

-- Course 7: إعدادات النظام والأمان (4 lessons)
('11111111-1111-1111-1111-111111111107', 'إعدادات النظام الأساسية', E'# إعدادات النظام الأساسية\n\n## الإعدادات العامة\n- **اسم المؤسسة**: يظهر في الواجهة والإشعارات\n- **اللغة الافتراضية**: العربية أو الإنجليزية\n- **المنطقة الزمنية**: لضبط التواريخ والأوقات\n- **الشعار**: شعار المؤسسة\n\n## إعدادات البريد\n- خادم SMTP للإشعارات\n- قوالب البريد الإلكتروني\n- عناوين الإرسال\n\n## إعدادات الإشعارات\n- تفعيل/تعطيل أنواع الإشعارات\n- قنوات الإشعار (بريد/نظام/واتساب)', 1, 9),
('11111111-1111-1111-1111-111111111107', 'إدارة المستخدمين والأدوار', E'# إدارة المستخدمين والأدوار\n\n## الأدوار المتاحة\n- **مدير النظام**: صلاحيات كاملة\n- **مدير قسم**: إدارة قسم محدد\n- **وكيل دعم**: معالجة التذاكر\n- **مستفيد**: تقديم ومتابعة التذاكر\n\n## إضافة مستخدم\n1. افتح **الإعدادات** > **المستخدمين**\n2. اضغط **إضافة مستخدم**\n3. أدخل البيانات الأساسية\n4. حدد الدور والقسم\n5. أرسل دعوة بالبريد\n\n## إدارة الصلاحيات\nكل دور له مجموعة صلاحيات محددة يمكن تعديلها', 2, 10),
('11111111-1111-1111-1111-111111111107', 'سياسات الأمان', E'# سياسات الأمان\n\n## المصادقة\n- **كلمة المرور**: متطلبات التعقيد والطول\n- **المصادقة الثنائية**: تفعيل 2FA\n- **تسجيل الدخول الموحد**: SSO عبر SAML\n\n## التحكم في الوصول\n- سياسات RLS على مستوى قاعدة البيانات\n- فصل البيانات بين المستأجرين\n- تشفير البيانات الحساسة\n\n## سجل المراجعة\n- تسجيل جميع العمليات\n- من قام بماذا ومتى\n- تتبع التغييرات على التذاكر والإعدادات\n- تصدير سجل المراجعة', 3, 8),
('11111111-1111-1111-1111-111111111107', 'النسخ الاحتياطي والاستعادة', E'# النسخ الاحتياطي والاستعادة\n\n## النسخ الاحتياطي التلقائي\n- نسخ يومية تلقائية\n- احتفاظ لمدة 30 يوماً\n- تخزين آمن ومشفر\n\n## النسخ اليدوي\n1. افتح **الإعدادات** > **النسخ الاحتياطي**\n2. اضغط **إنشاء نسخة الآن**\n3. انتظر اكتمال العملية\n4. حمّل النسخة للحفظ المحلي\n\n## استعادة البيانات\n- اختر النسخة المطلوبة\n- راجع محتوياتها\n- نفّذ الاستعادة\n- تحقق من سلامة البيانات\n\n> ⚠️ الاستعادة تستبدل البيانات الحالية', 4, 7),

-- Course 8: إدارة Multi-Tenant (4 lessons)
('11111111-1111-1111-1111-111111111108', 'مفهوم تعدد المستأجرين', E'# مفهوم تعدد المستأجرين (Multi-Tenant)\n\n## ما هو Multi-Tenant?\nبنية تسمح لعدة مؤسسات باستخدام نفس النظام مع:\n- **عزل البيانات**: كل مستأجر يرى بياناته فقط\n- **تخصيص الهوية**: شعار وألوان مختلفة لكل مستأجر\n- **إدارة مستقلة**: كل مستأجر يدير مستخدميه\n\n## الفوائد\n1. تقليل تكاليف التشغيل\n2. سهولة الصيانة والتحديث\n3. قابلية التوسع\n4. إدارة مركزية', 1, 8),
('11111111-1111-1111-1111-111111111108', 'إنشاء وإدارة المستأجرين', E'# إنشاء وإدارة المستأجرين\n\n## إنشاء مستأجر جديد\n1. افتح **الإعدادات** > **المستأجرين**\n2. اضغط **إضافة مستأجر**\n3. أدخل اسم المؤسسة والمعرف\n4. حدد خطة الاشتراك\n5. عيّن المالك\n\n## إعدادات المستأجر\n- **الخطة**: مجاني/أساسي/متقدم/مؤسسي\n- **الحدود**: عدد المستخدمين والتذاكر\n- **الميزات**: الميزات المتاحة حسب الخطة\n- **النطاق**: نطاق مخصص اختياري', 2, 10),
('11111111-1111-1111-1111-111111111108', 'تخصيص الهوية البصرية', E'# تخصيص الهوية البصرية\n\n## عناصر التخصيص\n- **الشعار**: شعار المؤسسة\n- **اللون الأساسي**: لون العلامة التجارية\n- **اللون الثانوي**: لون التمييز\n- **أيقونة الموقع**: Favicon مخصص\n\n## معاينة التخصيص\nيمكن معاينة التغييرات قبل التطبيق:\n1. ارفع الشعار الجديد\n2. اختر الألوان\n3. اضغط **معاينة**\n4. راجع المظهر\n5. اضغط **حفظ** للتطبيق\n\n## النطاق المخصص\nيمكن ربط نطاق خاص مثل `support.yourcompany.com`', 3, 8),
('11111111-1111-1111-1111-111111111108', 'إدارة الأعضاء والصلاحيات', E'# إدارة أعضاء المستأجر\n\n## أدوار المستأجر\n- **المالك**: صلاحيات كاملة على المستأجر\n- **مدير**: إدارة الإعدادات والمستخدمين\n- **عضو**: استخدام النظام فقط\n\n## إضافة أعضاء\n1. افتح **إعدادات المستأجر** > **الأعضاء**\n2. اضغط **دعوة عضو**\n3. أدخل البريد الإلكتروني\n4. حدد الدور\n5. أرسل الدعوة\n\n## مراقبة الاستخدام\n- عدد المستخدمين النشطين\n- عدد التذاكر الشهرية\n- استهلاك الموارد\n- تنبيهات عند اقتراب الحدود', 4, 7);
